<script setup lang="ts">
import { computed,ref,watch } from 'vue';
import { useRoute } from 'vue-router';
import { api,ApiError } from '../api/client';
import { useRemote } from '../composables/useRemote';
import { useSessionStore } from '../stores/session';
import { m4Names,syncBehaviors } from '../domain/m4';
import { shanghaiTime } from '../domain/m1';
import ErrorPanel from '../components/ErrorPanel.vue';
import M4Navigation from '../components/M4Navigation.vue';
import M4ConfirmAction from '../components/M4ConfirmAction.vue';
import M4EventGenerator from '../components/M4EventGenerator.vue';
const notice=ref('');
const eventAccepted=()=>{notice.value='Mock 事件已受理，等待后台独立核验。';void remote.load();};
const route=useRoute(),session=useSessionStore();const id=computed(()=>String(route.params.id));
const remote=useRemote(async()=>{const target=id.value;const result=await api.getShipment(target);if(result.id!==target)throw new ApiError('INVALID_RESPONSE','物流记录与当前包裹不符。');return result;});
watch(id,()=>{notice.value='';void remote.load();},{immediate:true});const behavior=ref('NORMAL');watch(()=>remote.data.value,v=>{if(v)behavior.value=v.config.behavior;});
const retry=computed(()=>{const target=id.value;return (key:string)=>api.retryShipmentSync(target,key);});
const configure=computed(()=>{const target=id.value,body={behavior:behavior.value,version:remote.data.value?.config.version??0};return (key:string)=>api.configureShipmentSync(target,body as never,key);});
</script>
<template><div><div class="page-heading"><div><p class="eyebrow">物流中心 / Mock 包裹详情</p><h1>物流包裹详情</h1><p class="muted">独立包裹、版本与下游同步记录</p></div><el-button :loading="remote.loading.value" @click="remote.load">刷新权威状态</el-button></div><M4Navigation /><p v-if="notice" class="success-note" role="status">{{ notice }}</p><div v-if="remote.loading.value" class="panel data-state" role="status"><el-skeleton :rows="5" animated /></div><ErrorPanel v-else-if="remote.error.value" :error="remote.error.value" :title="remote.error.value.status===404?'包裹不存在或不在访问范围':'物流详情读取失败'"><el-button @click="remote.load">重试</el-button></ErrorPanel><template v-else-if="remote.data.value"><section class="panel detail-panel"><h2>{{ remote.data.value.externalShipmentId }}</h2><dl class="order-facts"><div><dt>供应商来源状态</dt><dd>{{ m4Names[remote.data.value.sourceState] }} · {{ remote.data.value.sourceState }}</dd></div><div><dt>本地物流状态</dt><dd>{{ m4Names[remote.data.value.state] }} · {{ remote.data.value.state }}</dd></div><div><dt>下游权威回填</dt><dd>{{ m4Names[remote.data.value.currentSync?.state??'NOT_SENT'] }}<p>{{ remote.data.value.currentSync?.platformAck??'尚无权威回执' }}</p></dd></div><div><dt>当前运单 / 版本 / 数量</dt><dd>{{ remote.data.value.trackingNumber }} / {{ remote.data.value.trackingVersion }} / {{ remote.data.value.qty }}</dd></div><div><dt>补偿状态</dt><dd>{{ remote.data.value.currentSync?.lastErrorCode??'无' }} · 重试 {{ remote.data.value.currentSync?.retryCount??0 }} 次<p>{{ remote.data.value.currentSync?.state==='ACKED'?'本版本权威核验已完成':remote.data.value.currentSync?.needsQuery?'先查权威状态，冻结重复提交':'等待后台处理' }}</p></dd></div><div><dt>更新时间（上海）</dt><dd>{{ shanghaiTime(remote.data.value.updatedAt) }}</dd></div></dl><div class="inline-actions"><RouterLink class="text-link" :to="`/orders/${remote.data.value.salesOrderId}`">关联销售订单</RouterLink><RouterLink class="text-link" :to="`/purchases/${remote.data.value.purchaseOrderId}`">关联采购订单</RouterLink><M4ConfirmAction v-if="session.can('logistics.manage')&&['RETRY_WAIT','BLOCKED'].includes(remote.data.value.currentSync?.state??'')" testid="retry-shipment" label="申请同步补偿" :context="id" :run="retry" @done="remote.load" /></div><p class="help-text">提交成功、HTTP 200 或重试受理均不能作为 ACKED 依据；只有独立 Mock 权威核验通过后显示确认。</p></section><section class="panel detail-panel"><h2>运单版本历史</h2><div class="table-scroll"><table class="data-table"><thead><tr><th>版本</th><th>内部 Mock 运单</th><th>来源版本 / 数量</th><th>观测时间（上海）</th></tr></thead><tbody><tr v-for="v in remote.data.value.versions" :key="v.trackingVersion"><td>{{ v.trackingVersion }}</td><td>{{ v.trackingNumber }}</td><td>{{ v.sourceVersion }} / {{ v.qty }}</td><td>{{ shanghaiTime(v.observedAt) }}</td></tr></tbody></table></div><h3>各版本回填 / 回执</h3><div v-for="sync in remote.data.value.syncs" :key="sync.id" class="help-text"><strong>运单版本 {{ sync.trackingVersion }} · {{ m4Names[sync.state] }}</strong><p>{{ sync.platformAck??'尚无权威回执' }} · {{ sync.lastErrorCode??'无异常' }} · {{ shanghaiTime(sync.acknowledgedAt) }}</p></div></section><section v-if="session.can('logistics.manage')" class="panel detail-panel"><h2>Mock 回填故障配置</h2><form class="inline-form" @submit.prevent><label>故障（版本 {{ remote.data.value.config.version }}）<select v-model="behavior" name="syncBehavior"><option v-for="s in syncBehaviors" :key="s" :value="s">{{ m4Names[s] }}</option></select></label><M4ConfirmAction label="修改 Mock 同步配置" :context="`${id}:${behavior}:${remote.data.value.config.version}`" :run="configure" @done="remote.load" /></form></section><M4EventGenerator v-if="session.can('logistics.manage')" kind="shipment" :target-id="remote.data.value.purchaseOrderId" :shipment="remote.data.value" @done="eventAccepted" /></template></div></template>
